window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e78f66617f2e43a7"]={"versions": [{"id": "FIG-e78f66617f2e43a7", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Beispieldiagramm) im Rahmen der AUTOSAR XML Schema Production Rules (<code>AUTOSAR_TPS_XMLSchemaProductionRules</code>). Das Diagramm illustriert die Generierungsvorschrift für ein XML-Schema-Konstrukt (<code>xsd:complexType</code>) aus einer konkreten Metamodell-Klasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine einzelne Klasse:</p>\n<ul class=\"fig-list\"><li><strong>AUTOSAR</strong>: Konkrete, nicht-abstrakte UML-Klasse ohne dargestellte Attribute oder Operationen, dargestellt als rechteckiger Klassenkasten mit zentriertem Klassennamen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm. Es sind keine dynamischen Interaktionen, Nachrichtenaustausche oder Zustandsübergänge modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als normatives Anschauungsbeispiel für die Erzeugung eines <code>xsd:complexType</code> gemäß Regelwerk: Für eine nicht-abstrakte Klasse mit dem Namen <code>AUTOSAR</code> wird ein komplexer Typ (<code>&lt;xsd:complexType name=&quot;AUTOSAR&quot;&gt;</code>) generiert, der Verweise auf die zugehörige Gruppe (<code>&lt;xsd:group ref=&quot;AR:AUTOSAR&quot;/&gt;</code>) und Attributgruppe (<code>&lt;xsd:attributeGroup ref=&quot;AR:AUTOSAR&quot;/&gt;</code>) kapselt. Da die Klasse keine eigenen sichtbaren Attribute deklariert und nicht abstrakt ist, entsteht die minimale Basisschemastruktur für das Wurzelelement bzw. den Hauptkomplextyp.</p>"}, {"id": "FIG-b13d3ba48c75bbfb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Beispieldiagramm) im Rahmen der AUTOSAR XML Schema Production Rules (<code>AUTOSAR_TPS_XMLSchemaProductionRules</code>). Das Diagramm illustriert die Generierungsvorschrift für ein XML-Schema-Konstrukt (<code>xsd:complexType</code>) aus einer konkreten Metamodell-Klasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine einzelne Klasse:</p>\n<ul class=\"fig-list\"><li><strong>AUTOSAR</strong>: Konkrete, nicht-abstrakte UML-Klasse ohne dargestellte Attribute oder Operationen, dargestellt als rechteckiger Klassenkasten mit zentriertem Klassennamen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm. Es sind keine dynamischen Interaktionen, Nachrichtenaustausche oder Zustandsübergänge modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als normatives Anschauungsbeispiel für die Erzeugung eines <code>xsd:complexType</code> gemäß Regelwerk: Für eine nicht-abstrakte Klasse mit dem Namen <code>AUTOSAR</code> wird ein komplexer Typ (<code>&lt;xsd:complexType name=&quot;AUTOSAR&quot;&gt;</code>) generiert, der Verweise auf die zugehörige Gruppe (<code>&lt;xsd:group ref=&quot;AR:AUTOSAR&quot;/&gt;</code>) und Attributgruppe (<code>&lt;xsd:attributeGroup ref=&quot;AR:AUTOSAR&quot;/&gt;</code>) kapselt. Da die Klasse keine eigenen sichtbaren Attribute deklariert und nicht abstrakt ist, entsteht die minimale Basisschemastruktur für das Wurzelelement bzw. den Hauptkomplextyp.</p>"}], "trans": [{"from": "FIG-e78f66617f2e43a7", "to": "FIG-b13d3ba48c75bbfb", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
